-- GENERATED by scripts/generate-links-sql.ts from data/product-links.ts — do not edit by hand.
-- 37 direct product links (35 opened and checked), retailer search pages, and the "Peaches" registry name.

alter table public.retailers add column if not exists search_url_template text
  check (search_url_template is null or (search_url_template ~* '^https://' and position('{q}' in search_url_template) > 0));
alter table public.gift_retailers add column if not exists product_note text check (char_length(product_note) <= 300);

insert into public.retailers (slug, name, website_url, search_url_template, notes) values
  ('mom-store', 'Mom Store', 'https://www.momstore.com/ae-en/', 'https://www.momstore.com/ae-en/catalogsearch/result/?q={q}', 'UAE baby store (Lals Group) — online at momstore.com, stores reported at City Centre Mirdif and The Dubai Mall. Also stocks Carter''s.'),
  ('carters', 'Carter''s', 'https://ae.carters.com/', 'https://ae.carters.com/catalogsearch/result/?q={q}', 'Carter''s UAE online store. Carter''s is also sold in Mom Store.'),
  ('mamas-and-papas', 'Mamas & Papas UAE', 'https://mamasandpapas.ae/', null, 'Several items are listed here at exactly the prices in the original list.'),
  ('mumzworld', 'Mumzworld', 'https://www.mumzworld.com/en', 'https://www.mumzworld.com/en/search?q={q}', 'UAE online baby store.'),
  ('carrefour-uae', 'Carrefour UAE', null, null, null),
  ('centrepoint', 'Centrepoint', null, null, null)
on conflict (slug) do update set
  website_url = coalesce(public.retailers.website_url, excluded.website_url),
  search_url_template = coalesce(public.retailers.search_url_template, excluded.search_url_template),
  notes = coalesce(nullif(public.retailers.notes, ''), excluded.notes);

