insert into public.gift_retailers (gift_id, retailer_id, product_url, url_verified, product_note, is_primary)
select g.id, r.id, v.url, v.verified, v.note, true
  from v join public.gifts g on g.slug = v.gift_slug join public.retailers r on r.slug = v.retailer_slug
on conflict (gift_id, retailer_id) do update set
  product_url = excluded.product_url, url_verified = excluded.url_verified,
  product_note = excluded.product_note, is_primary = true
  where public.gift_retailers.product_url is null;

-- The retailer with the direct link becomes the gift's primary shop.
update public.gift_retailers gr set is_primary = false
  from public.gift_retailers linked
 where linked.gift_id = gr.gift_id and linked.id <> gr.id
   and linked.product_url is not null and gr.product_url is null and gr.is_primary;

-- The baby's nickname. Only replaces the original defaults, never text the family has edited.
update public.registry_settings set registry_title = 'Baby Peaches' where id = 1 and registry_title = 'Our Baby Registry';
update public.registry_settings set welcome_heading = 'Made with love for little Peaches.' where id = 1 and welcome_heading = 'Made with love for our little one.';
